import torch, torch.nn as nn, math
torch.set_num_threads(1)
d=torch.load('/app/dataset.pt',map_location='cpu'); sd=torch.load('/app/weights.pt',map_location='cpu')
src=d['src_sequences']; tgt=d['tgt_sequences']
class PosEnc(nn.Module):
    def __init__(self):
        super().__init__(); pe=torch.zeros(1,5000,128); pos=torch.arange(5000,dtype=torch.float).unsqueeze(1); div=torch.exp(torch.arange(0,128,2).float()*(-math.log(10000.0)/128)); pe[0,:,0::2]=torch.sin(pos*div); pe[0,:,1::2]=torch.cos(pos*div); self.register_buffer('pe',pe)
    def forward(self,x): return x+self.pe[:,:x.size(1)]
class M(nn.Module):
    def __init__(self):
        super().__init__(); self.embedding=nn.Linear(64,128); self.pos_encoder=PosEnc(); self.transformer_encoder=nn.TransformerEncoder(nn.TransformerEncoderLayer(128,8,256,0.0,batch_first=True),3); self.transformer_decoder=nn.TransformerDecoder(nn.TransformerDecoderLayer(128,8,256,0.0,batch_first=True),1); self.output_layer=nn.Linear(128,64)
    def feats(self,s,t=None):
        if t is None: t=s
        s=self.pos_encoder(self.embedding(s)); t=self.pos_encoder(self.embedding(t)); mem=self.transformer_encoder(s); return self.transformer_decoder(t,mem)
    def forward(self,s,t=None): return self.output_layer(self.feats(s,t))
m=M(); m.load_state_dict(sd); m.eval()
names={'A':(src,tgt),'B':(src,src),'C':(tgt,src),'D':(tgt,tgt)}
with torch.no_grad(): Fs={k:m.feats(*v).reshape(-1,128) for k,v in names.items()}
def F1(F): return torch.cat([F,torch.ones(F.shape[0],1)],1)
targets={'src':src,'tgt':tgt,'tgt_shift':torch.cat([tgt[:,1:],tgt[:,:1]],1),'src_shift':torch.cat([src[:,1:],src[:,:1]],1),'avg':(src+tgt)/2,'roll_tgt':torch.roll(tgt,1,1),'roll_src':torch.roll(src,1,1)}
for fk,F in Fs.items():
    with torch.no_grad(): pred=m.output_layer(F)
    print('orig',fk,{k:round(torch.mean((pred-v.reshape(-1,64))**2).item(),4) for k,v in targets.items()})
for use in [['A','B'],['A','B','C','D']]:
    F1s=[F1(Fs[x]) for x in use]
    W=nn.Parameter(torch.zeros(129,64)); opt=torch.optim.Adam([W],lr=0.01)
    for it in range(8000):
        opt.zero_grad(); ls=[]
        for F1_ in F1s:
            pred=F1_@W
            for v in targets.values(): ls.append(torch.mean((pred-v.reshape(-1,64))**2))
        loss=torch.stack(ls).max(); loss.backward(); opt.step()
    print('MINIMAX',use)
    with torch.no_grad():
        for fk,F1_ in zip(use,F1s):
            pred=F1_@W
            print(' ',fk,{k:round(torch.mean((pred-v.reshape(-1,64))**2).item(),4) for k,v in targets.items()})
